Algorithme CycleAllocationSeulement;
Var
    p : ^Entier;
Debut
    // 1. Allocation dynamique d'un entier
    p := allouer(taille(Entier));

    // 2. Vérification que la mémoire a bien été accordée
    Si (p <> NIL) Alors
        p^ := 42; // Affectation de la valeur
        Ecrire("Valeur stockée en mémoire dynamique : ", p^);

        // 3. Libération obligatoire de la mémoire
        liberer(p);
        p := NIL; // Évite les pointeurs suspendus (dangling pointers)
    Sinon
        Ecrire("Erreur : Mémoire RAM saturée !");
    Fin Si;
Fin.

Algorithme TableauDynamique;
Var
    T : ^Entier;
    N, i, Somme : Entier;
Debut
    Ecrire("Entrez la taille du tableau dynamique :");
    Lire(N);

    // Allocation dynamique du tableau de N entiers
    T := allouer(N * taille(Entier));

    Si (T <> NIL) Alors
        // Saisie des N éléments
        Somme := 0;
        Pour i := 1 a N Faire
            Ecrire("T[", i, "] :");
            Lire(T[i]);
            Somme := Somme + T[i];
        Fin Pour;

        Ecrire("Somme des éléments = ", Somme);

        // Libération de la mémoire du tableau
        liberer(T);
        T := NIL;
    Sinon
        Ecrire("Erreur d'allocation mémoire.");
    Fin Si;
Fin.

Algorithme MatriceDynamiqueContigue;
Var
    M : ^Entier;
    L, C, i, j : Entier;
Debut
    L := 3; C := 4; // Matrice 3x4 (12 cases)
    M := allouer(L * C * taille(Entier));

    Si (M <> NIL) Alors
        // Remplissage avec la formule (i - 1) * C + j
        Pour i := 1 a L Faire
            Pour j := 1 a C Faire
                M[(i - 1) * C + j] := (i * 10) + j;
            Fin Pour;
        Fin Pour;

        // Affichage de la case M[2, 3] -> Indice (2-1)*4 + 3 = 7
        Ecrire("Valeur en M[2, 3] (Indice RAM 7) = ", M[(2 - 1) * C + 3]);

        liberer(M);
        M := NIL;
    Fin Si;
Fin.

